INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass kleine Firmen immer teure IT-Lösungen brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosteneffiziente Lösungen sind oft besser"}, {"text": "Ja", "correct": false, "because": "Budget ist begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine IT-Lösung für ein kleines Unternehmen wähle?', 3, '[{"text": "Kosteneffizienz", "correct": true, "because": "Passt zu begrenztem Budget"}, {"text": "Maximale Leistung", "correct": false, "because": "Oft überdimensioniert"}, {"text": "Luxuriöses Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche IT-Lösungen sind für kleine Firmen sinnvoll?', 5, '[{"text": "Cloud-Speicher", "correct": true, "because": "Skalierbar und günstig"}, {"text": "Open-Source-Software", "correct": true, "because": "Reduziert Lizenzkosten"}, {"text": "Hochpreisige Server", "correct": false, "because": "Zu teuer"}, {"text": "Exklusive Hardware", "correct": false, "because": "Nicht notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kleine Firmen profitieren von skalierbaren Lösungen. b) Sie brauchen immer eigene Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Server oft nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk für ein kleines Unternehmen einrichte?', 4, '[{"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützen Daten"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Luxusbüro", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob kleine Firmen immer eigene IT-Abteilungen brauchen?', 2, '[{"text": "Nein", "correct": true, "because": "Auslagerung ist oft günstiger"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich eine Backup-Lösung für ein mittleres Unternehmen wähle?', 3, '[{"text": "Datenverfügbarkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Höchste Kosten", "correct": false, "because": "Budget ist wichtig"}, {"text": "Komplexe Systeme", "correct": false, "because": "Einfachheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen IT-Lösungen für kleine Firmen effektiv?', 5, '[{"text": "Einfache Wartung", "correct": true, "because": "Reduziert Aufwand"}, {"text": "Geringe Kosten", "correct": true, "because": "Passt zu Budget"}, {"text": "Maximale Leistung", "correct": false, "because": "Oft überdimensioniert"}, {"text": "Exklusive Marken", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Cloud-Lösungen sparen Kosten bei kleinen Firmen. b) Sie brauchen immer teure Lizenzen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lizenzen oft günstig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich eine IT-Lösung für ein kleines Unternehmen einführe?', 4, '[{"text": "Benutzerfreundlichkeit", "correct": false, "because": "Wichtig für kleine Teams"}, {"text": "Kostenkontrolle", "correct": false, "because": "Schützt Budget"}, {"text": "Luxusdesign", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen mittlere Unternehmen immer teure Software kaufen?', 2, '[{"text": "Nein", "correct": true, "because": "Open-Source oft ausreichend"}, {"text": "Ja", "correct": false, "because": "Kosteneffizienz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Cloud-Lösung für ein kleines Unternehmen?', 4, '[{"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Wachstum an"}, {"text": "Geringer Wartungsaufwand", "correct": true, "because": "Anbieter übernimmt"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Kosten sind niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass kleine Firmen keine IT-Sicherheit brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit ist für alle wichtig"}, {"text": "Ja", "correct": false, "because": "Risiken betreffen alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die IT-Kosten eines mittleren Unternehmens zu senken?', 3, '[{"text": "Virtualisierung", "correct": true, "because": "Nutzt Ressourcen effizient"}, {"text": "Teure Server", "correct": false, "because": "Erhöht Kosten"}, {"text": "Luxusgeräte", "correct": false, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) KMU profitieren von einfachen IT-Lösungen. b) Sie brauchen immer große IT-Teams.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teams oft klein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei IT-Lösungen für kleine Firmen?', 5, '[{"text": "Einfache Bedienung", "correct": true, "because": "Reduziert Schulungsaufwand"}, {"text": "Kosteneffizienz", "correct": true, "because": "Schützt Budget"}, {"text": "Exklusive Hardware", "correct": false, "because": "Zu teuer"}, {"text": "Komplexe Systeme", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Netzwerk für ein kleines Unternehmen einrichte?', 3, '[{"text": "Sicherheitsprotokolle", "correct": false, "because": "Schützen Daten"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Designergeräte", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen kleine Firmen immer lokale Server nutzen?', 3, '[{"text": "Nein", "correct": true, "because": "Cloud oft günstiger"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob mittlere Unternehmen von Open-Source profitieren?', 2, '[{"text": "Ja", "correct": true, "because": "Reduziert Kosten"}, {"text": "Nein", "correct": false, "because": "Oft vorteilhaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich IT für ein kleines Unternehmen plane?', 4, '[{"text": "Flexibilität", "correct": true, "because": "Passt sich Bedarf an"}, {"text": "Teure Lizenzen", "correct": false, "because": "Zu kostspielig"}, {"text": "Luxusausstattung", "correct": false, "because": "Irrelevant"}]');
